WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true ) ) ) SELECT row_to_json((SELECT "%" FROM (SELECT row_to_json((SELECT "%" FROM (SELECT count( "t0" .*) AS "count" ) AS "%")) AS "aggregate" , coalesce(json_agg( "c1"."j" ), '[]') AS "nodes" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT 'author' AS "__typename" ) AS "%")) AS "j" FROM (SELECT true) AS "_" ) AS "c1" ON true
